build_hemo_dict.function_str:
def _build_hemodynamic_dict(
    mtt: str,
    rel_cbf: str,
    rel_cbv: str,
    ncbf: str,
    ncbv: str,
) -> dict[str, str]:
    from pathlib import Path as _P
    d = {"mtt": mtt, "rel_cbf": rel_cbf, "rel_cbv": rel_cbv}
    for name, val in [
        ("ncbf", ncbf), ("ncbv", ncbv),
    ]:
        if isinstance(val, str) and val not in ("", "None") and _P(val).is_file():
            d[name] = val
    return d

